def parseTernaryStack(expression):
    stack = []

    # Process from right to left
    i = len(expression) - 1
    while i >= 0:
        char = expression[i]

        if char == '?':
            # Pop true_val and false_val; the condition is the character just before '?'
            true_val = stack.pop()
            false_val = stack.pop()
            condition = expression[i - 1]

            # Push result back to stack
            if condition == 'T':
                stack.append(true_val)
            else:
                stack.append(false_val)
            i -= 2  # skip the condition as well
        else:
            if char != ':':
                # Push operand to stack (':' is just a separator)
                stack.append(char)
            i -= 1

    return stack[0]

