def parseTernaryIterative(expression):
    def find_matching_colon(expr):
        """Find the colon that matches the '?' at index 1 of expr."""
        count = 0
        for i in range(2, len(expr)):
            if expr[i] == '?':
                count += 1
            elif expr[i] == ':':
                if count == 0:
                    return i
                count -= 1
        return -1

    def evaluate(expr):
        if len(expr) == 1:
            return expr

        condition = expr[0]
        colon_pos = find_matching_colon(expr)

        true_part = expr[2:colon_pos]
        false_part = expr[colon_pos + 1:]

        if condition == 'T':
            return evaluate(true_part)
        else:
            return evaluate(false_part)

    return evaluate(expression)

