def parseTernaryDeque(expression):
    from collections import deque

    stack = deque()

    # Process from right to left
    i = len(expression) - 1
    while i >= 0:
        char = expression[i]
        if char == '?':
            # The stack holds true and false values; the condition is just before '?'
            true_val = stack.pop()
            false_val = stack.pop()
